<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import type {Console,Row} from '../console';
import Icon from './Icon.vue';import OriginsList from './OriginsList.vue';
const props=defineProps<{c:Console}>();const selected=ref(''),inherited=ref(''),query=ref(''),origins=ref<Row[]>([]),loading=ref(false);
let revision=0;
watch(()=>props.c.s.refreshVersion,()=>{void load();});
const role=computed(()=>props.c.s.roles.find(r=>r.id===Number(selected.value)));
const edges=computed(()=>props.c.s.edges.filter(e=>e.seniorRoleId===Number(selected.value)));
const filtered=computed(()=>props.c.s.roles.filter(r=>(r.name+' '+r.code).toLowerCase().includes(query.value.toLowerCase())));
const candidates=computed(()=>props.c.s.roles.filter(r=>r.id!==Number(selected.value)&&r.enabled&&!edges.value.some(e=>e.inheritedRoleId===r.id)));
watch(()=>props.c.s.roles,roles=>{if(!roles.some(r=>r.id===Number(selected.value)))selected.value=String(roles[0]?.id||'');},{immediate:true});
watch(selected,()=>{inherited.value='';void load();},{immediate:true});
async function load(){const version=++revision;origins.value=[];if(!selected.value)return;loading.value=true;try{const result=await props.c.api(`/api/roles/${selected.value}/effective-permissions`);if(version===revision)origins.value=result;}catch(e){if(version===revision)props.c.message((e as Error).message,true);}finally{if(version===revision)loading.value=false;}}
async function add(){if(!selected.value||!inherited.value)return;const target=props.c.s.roles.find(r=>r.id===Number(inherited.value));if(!await props.c.ask('建立角色继承',`“${role.value?.name}”将获得“${target?.name}”的有效权限，包括后者继续继承的权限。系统会校验是否成环。`,false))return;await props.c.run(async()=>{await props.c.api(`/api/roles/${selected.value}/inherits/${inherited.value}`,'PUT');inherited.value='';await props.c.refresh();await load();props.c.message('继承关系已建立，后续访问将使用新权限');});}
async function remove(id:number,name:string){if(!await props.c.ask('解除继承关系',`“${role.value?.name}”将不再通过这条关系获得“${name}”的权限。其他有效路径及直接授权会保留。`))return;await props.c.run(async()=>{await props.c.api(`/api/roles/${selected.value}/inherits/${id}`,'DELETE');await props.c.refresh();await load();props.c.message('继承关系已解除');});}
</script>
<template><div class="info-strip"><Icon name="info"/><span><strong>继承方向：</strong>高级角色 → 被继承角色。高级角色获得后者的权限；部门层级和菜单层级不会自动产生角色继承。</span><span class="badge indigo">RBAC1</span></div><div class="hierarchy-layout"><section class="panel role-picker"><div class="section-heading"><h2>选择角色</h2><span class="count">{{c.s.roles.length}}</span></div><div class="search-field compact-search"><Icon name="search"/><input v-model="query" placeholder="搜索角色…" aria-label="搜索角色"></div><div class="role-list"><button v-for="r in filtered" :key="r.id" :class="['role-option',{selected:Number(selected)===r.id}]" :disabled="c.s.busy" @click="selected=String(r.id)"><span class="resource-icon"><Icon name="shield"/></span><span><strong>{{r.name}}</strong><small>{{r.code}}</small></span><i v-if="!r.enabled" class="badge neutral">停用</i><Icon v-else name="chevron" :size="15"/></button><div v-if="!filtered.length" class="empty compact"><p>暂无角色，请先在角色管理中创建。</p></div></div></section><div class="hierarchy-main"><section class="panel"><div class="section-heading"><div><p class="eyebrow">ROLE INHERITANCE</p><h2>{{role?.name||'尚未选择角色'}}</h2></div><span :class="['badge',role?.enabled?'green':'neutral']"><i/>{{role?.enabled?'角色已启用':'角色未启用'}}</span></div><p class="muted">下列角色向当前角色提供权限。继承支持多级传递，系统拒绝形成闭环的关系。</p><div class="inheritance-flow"><div class="senior-card"><span class="resource-icon"><Icon name="shield" :size="23"/></span><div><small>获得权限的角色</small><h3>{{role?.name||'请选择角色'}}</h3><code>{{role?.code||'—'}}</code></div><span class="badge green">高级角色</span></div><div class="flow-connector"><span/>继承以下角色的权限<Icon name="arrow"/><span/></div><div class="inherited-grid"><article v-for="edge in edges" :key="edge.inheritedRoleId" class="inherited-card"><Icon name="shield"/><div><strong>{{edge.inheritedRoleName}}</strong><small>{{c.s.roles.find(r=>r.id===edge.inheritedRoleId)?.enabled?'权限沿此路径传递':'已停用 · 此路径被阻断'}}</small></div><button class="icon-button subtle-danger" :aria-label="'解除继承'+edge.inheritedRoleName" :disabled="c.s.busy" @click="remove(edge.inheritedRoleId,edge.inheritedRoleName)"><Icon name="close" :size="15"/></button></article><div v-if="!edges.length" class="inherit-empty">暂未继承其他角色，可在下方建立第一条关系。</div></div></div><div class="inheritance-form"><label>被继承角色<select aria-label="被继承角色" v-model="inherited" :disabled="!role?.enabled||c.s.busy"><option value="">选择要继承权限的角色</option><option v-for="r in candidates" :key="r.id" :value="r.id">{{r.name}} · {{r.code}}</option></select></label><button class="primary" :disabled="!inherited||!role?.enabled||c.s.busy" @click="add"><Icon name="plus"/>建立继承</button></div></section><section class="panel"><div class="section-heading"><div><h2>有效权限预览</h2><p class="muted">{{role?.name||'当前角色'}}的直接权限与继承权限，按权限去重。</p></div><button class="icon-button" aria-label="刷新有效权限" :disabled="loading||c.s.busy" @click="load"><Icon name="refresh"/></button></div><p v-if="loading" class="loading-line">正在计算有效权限…</p><OriginsList v-else :items="origins" :roles="c.s.roles"/></section></div></div></template>
